using System.Linq;using UnityEngine;using UnityEngine.AI;using AntColony.Buildings;
public static class FurnitureSurface1115
{
 public static string Main(){return string.Join("\n",Object.FindObjectsByType<BuildingBase>().Where(b=>FurnitureUseSurface.Supported(b)).Select(b=>{var v=b.GetComponent<FacilityVisual>();if(!v||!v.Model)return b.name+" no model";var points=v.Model.GetComponentsInChildren<MeshFilter>().Where(f=>f.sharedMesh&&f.sharedMesh.isReadable).SelectMany(f=>f.sharedMesh.vertices.Select(p=>b.transform.InverseTransformPoint(f.transform.TransformPoint(p)))).ToArray();if(points.Length==0)return b.name+" no readable mesh";float a=points.Min(p=>p.z),z=points.Max(p=>p.z),x=(points.Min(p=>p.x)+points.Max(p=>p.x))*.5f;float sign=b.Data.kind==AntColony.Data.BuildingKind.Bookshelf?1:-1;var desired=b.transform.TransformPoint(new Vector3(x,points.Min(p=>p.y),sign<0?a:z))+b.transform.forward*sign*.48f;bool nav=NavMesh.SamplePosition(desired,out var h,2,NavMesh.AllAreas);bool okay=FurnitureUseSurface.TryPoint(b,out var stand,out var surface);return $"{b.name} points={points.Length} x={x} z={a}/{z} topCount={points.Count(p=>Mathf.Abs(p.x-x)<.3f&&(sign<0?p.z<a+(z-a)*.35f:p.z>z-(z-a)*.35f))} desired={desired} nav={nav} nearest={h.position} distance={Vector3.Distance(desired,h.position)} okay={okay}";}));}
}
